// Máquina de estados de la conversación (una sesión por chat de Telegram).
// El estado vive en los datos estáticos del flujo (solo persisten con el flujo PUBLICADO).
const msg = $input.first().json.message || {};
const chatId = msg.chat && msg.chat.id;
const texto = (msg.text || '').trim();
const nombreTg = (msg.from && msg.from.first_name) || '';
const store = $getWorkflowStaticData('global');
store.sesiones = store.sesiones || {};

const responder = (accion, textoRespuesta, extra = {}) => [{ json: { chat_id: chatId, accion, texto: textoRespuesta, ...extra } }];

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Mexico_City' }).format(new Date());

function fechaISO(t) {
  let iso = null;
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(t);
  if (m) iso = `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  m = /^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/.exec(t);
  if (m) iso = `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  if (!iso) return null;
  const d = new Date(`${iso}T00:00:00Z`);
  return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== iso ? null : iso;
}
const noches = (a, b) => Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 86400000);
const mxn = (n) => `$${Number(n).toFixed(2)} MXN`;

if (!chatId || !msg.text) {
  return responder('preguntar', 'Envíame un mensaje de texto, por favor. Escribe /reservar para empezar.');
}

const cmd = texto.toLowerCase();
let s = store.sesiones[chatId];
if (s && Date.now() - s.ts > 30 * 60 * 1000) s = null; // sesión inactiva > 30 min

if (cmd === '/cancelar') {
  delete store.sesiones[chatId];
  return responder('preguntar', 'Reserva cancelada. Escribe /reservar cuando quieras empezar de nuevo.');
}

if (cmd === '/start' || cmd === '/reservar' || !s) {
  store.sesiones[chatId] = { paso: 'nombre', datos: {}, ts: Date.now() };
  return responder('preguntar',
    `Hola ${nombreTg}. Soy el bot de reservas del hotel. Te haré unas preguntas para registrar tu reserva (en cualquier momento escribe /cancelar).\n\n¿Cuál es tu nombre (o nombres)?`);
}

s.ts = Date.now();
const d = s.datos;

switch (s.paso) {
  case 'nombre':
    if (texto.length < 2 || texto.length > 80) return responder('preguntar', 'Escribe tu nombre (entre 2 y 80 caracteres).');
    d.nombre = texto;
    s.paso = 'apellidos';
    return responder('preguntar', '¿Y tus apellidos?');

  case 'apellidos':
    if (texto.length < 2 || texto.length > 100) return responder('preguntar', 'Escribe tus apellidos (entre 2 y 100 caracteres).');
    d.apellidos = texto;
    s.paso = 'correo';
    return responder('preguntar', '¿Cuál es tu correo electrónico? (ahí te enviaremos la confirmación)');

  case 'correo':
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(texto)) return responder('preguntar', 'Ese correo no parece válido. Ejemplo: nombre@correo.com');
    d.email = texto.toLowerCase();
    s.paso = 'entrada';
    return responder('preguntar', '¿Qué día llegas? Escribe la fecha como AAAA-MM-DD (por ejemplo 2026-12-20) o DD/MM/AAAA.');

  case 'entrada': {
    const f = fechaISO(texto);
    if (!f) return responder('preguntar', 'No entendí la fecha. Usa AAAA-MM-DD (2026-12-20) o DD/MM/AAAA.');
    if (f < hoy) return responder('preguntar', 'La fecha de llegada no puede ser anterior a hoy. Intenta con otra.');
    d.entrada = f;
    s.paso = 'salida';
    return responder('preguntar', '¿Qué día te vas? (misma forma: AAAA-MM-DD)');
  }

  case 'salida': {
    const f = fechaISO(texto);
    if (!f) return responder('preguntar', 'No entendí la fecha. Usa AAAA-MM-DD (2026-12-23) o DD/MM/AAAA.');
    if (f <= d.entrada) return responder('preguntar', `La salida debe ser después de la llegada (${d.entrada}). Intenta de nuevo.`);
    if (noches(d.entrada, f) > 30) return responder('preguntar', 'Por este medio solo se reservan hasta 30 noches. Escribe otra fecha de salida.');
    d.salida = f;
    s.paso = 'habitacion';
    return responder('disponibilidad', '', { datos: { ...d } }); // el flujo consulta la API y arma la lista
  }

  case 'habitacion': {
    const numero = texto.replace(/^hab(itaci[oó]n)?\s*/i, '').trim();
    const hab = (s.disponibles || []).find((h) => String(h.numero).toLowerCase() === numero.toLowerCase());
    if (!hab) {
      const lista = (s.disponibles || []).map((h) => h.numero).join(', ');
      return responder('preguntar', `No encontré esa habitación. Elige una de estas: ${lista}.`);
    }
    d.habitacionId = hab.habitacionId;
    d.numero = hab.numero;
    d.tipo = hab.tipo;
    d.numAdultos = Math.min(2, hab.capacidad);
    d.total = noches(d.entrada, d.salida) * hab.precioBase;
    s.paso = 'confirmar';
    return responder('preguntar',
      `Confirma tu reserva:\n👤 ${d.nombre} ${d.apellidos}\n📧 ${d.email}\n🛏️ Habitación ${d.numero} (${d.tipo}) para ${d.numAdultos} adulto(s)\n📅 Entrada: ${d.entrada}\n📅 Salida: ${d.salida} (${noches(d.entrada, d.salida)} noche(s))\n💰 Total: ${mxn(d.total)}\n\nResponde SI para confirmar o /cancelar.`);
  }

  case 'confirmar':
    if (['si', 'sí', 's', 'confirmo', 'confirmar'].includes(cmd)) {
      delete store.sesiones[chatId];
      return responder('registrar', '', { datos: { ...d, telegramChatId: chatId } });
    }
    if (cmd === 'no') {
      delete store.sesiones[chatId];
      return responder('preguntar', 'De acuerdo, no registré nada. Escribe /reservar para empezar de nuevo.');
    }
    return responder('preguntar', 'Responde SI para confirmar o NO / /cancelar para salir.');

  default:
    delete store.sesiones[chatId];
    return responder('preguntar', 'Algo salió mal. Escribe /reservar para empezar de nuevo.');
}

// Arma la lista de habitaciones libres y la guarda en la sesión para validar la elección.
const chatId = $('Conversación').first().json.chat_id;
const store = $getWorkflowStaticData('global');
store.sesiones = store.sesiones || {};
const s = store.sesiones[chatId];
const libres = $input.all().map((i) => i.json).filter((h) => h && h.habitacionId !== undefined);

if (!s) return [{ json: { chat_id: chatId, texto: 'La sesión expiró. Escribe /reservar para empezar de nuevo.' } }];

if (libres.length === 0) {
  s.paso = 'entrada';
  return [{ json: { chat_id: chatId, texto: 'No hay habitaciones libres en esas fechas 😕. Escribe otra fecha de llegada (AAAA-MM-DD) o /cancelar.' } }];
}

s.disponibles = libres;
const d = s.datos;
const n = Math.round((Date.parse(`${d.salida}T00:00:00Z`) - Date.parse(`${d.entrada}T00:00:00Z`)) / 86400000);
const filas = libres.map((h) => `🛏️ ${h.numero} · ${h.tipo} · hasta ${h.capacidad} pers. · $${Number(h.precioBase).toFixed(2)}/noche`);
return [{ json: { chat_id: chatId, texto: `Habitaciones libres del ${d.entrada} al ${d.salida} (${n} noche(s)):\n\n${filas.join('\n')}\n\nEscribe el número de la habitación que quieres (por ejemplo 101).` } }];

const email = $('Conversación').first().json.datos.email;
const existente = $input.all().map((i) => i.json).find((g) => g && g.email === email);
return [{ json: { huespedId: existente ? existente.id : null } }];

const prev = $input.first().json;
const d = $('Conversación').first().json.datos;
const huespedId = prev.huespedId != null ? prev.huespedId : (prev.body && prev.body.id);
return [{ json: { reserva: {
  huespedId,
  fechaEntrada: d.entrada,
  fechaSalida: d.salida,
  numAdultos: d.numAdultos,
  origen: 'telegram',
  estado: 'pendiente',
  notas: 'Reserva hecha por el bot de Telegram',
  habitaciones: [{ habitacionId: d.habitacionId }],
} } }];
